select throws_ok($$select public.get_game_score(gen_random_uuid())$$,'42501',null,'anonymous cannot read private judge snapshot');
select throws_ok($$select public.score_command(gen_random_uuid(),gen_random_uuid(),'point','a',0,true)$$,'42501',null,'anonymous cannot score');
reset role;
select * from finish();
rollback;
